<?php

declare(strict_types=1);

namespace Tests\Generated\MyCrud\Inventory;

use CodeIgniter\Test\CIUnitTestCase;

/**
 * Structural smoke test generated by myCrudCI4.
 *
 * Verifies that the components required by the architecture are published and
 * loadable through the autoloader. It does not access application data.
 */
final class InventoryStructureTest extends CIUnitTestCase
{
    private const EXPECTED_CLASSES = array (
  0 => 'App\\Models\\InventoryModel',
  1 => 'App\\Controllers\\InventoryController',
  2 => 'App\\Validation\\InventoryRules',
  3 => 'App\\Entities\\InventoryEntity',
  4 => 'App\\Services\\InventoryService',
  5 => 'App\\Controllers\\Api\\V1\\InventoryApiController',
  6 => 'App\\API\\Resources\\InventoryResource',
  7 => 'App\\Validation\\InventoryApiRules',
);

    public function testGeneratedClassesAreAutoloadable(): void
    {
        foreach (self::EXPECTED_CLASSES as $class) {
            $this->assertTrue(
                class_exists($class),
                'Generated class is not autoloadable: ' . $class
            );
        }
    }
}
